     1→import {ChainConfig} from "@lodestar/config";
     2→import {
     3→  KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH,
     4→  KZG_COMMITMENTS_SUBTREE_INDEX,
     5→  NUMBER_OF_COLUMNS,
     6→} from "@lodestar/params";
     7→import {computeStartSlotAtEpoch, getBlockHeaderProposerSignatureSet} from "@lodestar/state-transition";
     8→import {Root, Slot, SubnetID, fulu, ssz} from "@lodestar/types";
     9→import {toRootHex, verifyMerkleBranch} from "@lodestar/utils";
    10→import {Metrics} from "../../metrics/metrics.js";
    11→import {kzg} from "../../util/kzg.js";
    12→import {
    13→  DataColumnSidecarErrorCode,
    14→  DataColumnSidecarGossipError,
    15→  DataColumnSidecarValidationError,
    16→} from "../errors/dataColumnSidecarError.js";
    17→import {GossipAction} from "../errors/gossipValidation.js";
    18→import {IBeaconChain} from "../interface.js";
    19→import {RegenCaller} from "../regen/interface.js";
    20→
    21→// SPEC FUNCTION
    22→// https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#data_column_sidecar_subnet_id
    23→export async function validateGossipDataColumnSidecar(
    24→  chain: IBeaconChain,
    25→  dataColumnSidecar: fulu.DataColumnSidecar,
    26→  gossipSubnet: SubnetID,
    27→  metrics: Metrics | null
    28→): Promise<void> {
    29→  const blockHeader = dataColumnSidecar.signedBlockHeader.message;
    30→
    31→  // 1) [REJECT] The sidecar is valid as verified by verify_data_column_sidecar
    32→  verifyDataColumnSidecar(dataColumnSidecar);
    33→
    34→  // 2) [REJECT] The sidecar is for the correct subnet -- i.e. compute_subnet_for_data_column_sidecar(sidecar.index) == subnet_id
    35→  if (computeSubnetForDataColumnSidecar(chain.config, dataColumnSidecar) !== gossipSubnet) {
    36→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
    37→      code: DataColumnSidecarErrorCode.INVALID_SUBNET,
    38→      columnIdx: dataColumnSidecar.index,
    39→      gossipSubnet: gossipSubnet,
    40→    });
    41→  }
    42→
    43→  // 3) [IGNORE] The sidecar is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance)
    44→  //             -- i.e. validate that sidecar.slot <= current_slot (a client MAY queue future blocks
    45→  //             for processing at the appropriate slot).
    46→  const currentSlotWithGossipDisparity = chain.clock.currentSlotWithGossipDisparity;
    47→  if (currentSlotWithGossipDisparity < blockHeader.slot) {
    48→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    49→      code: DataColumnSidecarErrorCode.FUTURE_SLOT,
    50→      currentSlot: currentSlotWithGossipDisparity,
    51→      blockSlot: blockHeader.slot,
    52→    });
    53→  }
    54→
    55→  // 4) [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that
    56→  //             sidecar.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
    57→  const finalizedCheckpoint = chain.forkChoice.getFinalizedCheckpoint();
    58→  const finalizedSlot = computeStartSlotAtEpoch(finalizedCheckpoint.epoch);
    59→  if (blockHeader.slot <= finalizedSlot) {
    60→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    61→      code: DataColumnSidecarErrorCode.WOULD_REVERT_FINALIZED_SLOT,
    62→      blockSlot: blockHeader.slot,
    63→      finalizedSlot,
    64→    });
    65→  }
    66→
    67→  // 6) [IGNORE] The sidecar's block's parent (defined by block_header.parent_root) has been seen (via gossip
    68→  //             or non-gossip sources)
    69→  const parentRoot = toRootHex(blockHeader.parentRoot);
    70→  const parentBlock = chain.forkChoice.getBlockHex(parentRoot);
    71→  if (parentBlock === null) {
    72→    // If fork choice does *not* consider the parent to be a descendant of the finalized block,
    73→    // then there are two more cases:
    74→    //
    75→    // 1. We have the parent stored in our database. Because fork-choice has confirmed the
    76→    //    parent is *not* in our post-finalization DAG, all other blocks must be either
    77→    //    pre-finalization or conflicting with finalization.
    78→    // 2. The parent is unknown to us, we probably want to download it since it might actually
    79→    //    descend from the finalized root.
    80→    // (Non-Lighthouse): Since we prune all blocks non-descendant from finalized checking the `db.block` database won't be useful to guard
    81→    // against known bad fork blocks, so we throw PARENT_UNKNOWN for cases (1) and (2)
    82→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    83→      code: DataColumnSidecarErrorCode.PARENT_UNKNOWN,
    84→      parentRoot,
    85→    });
    86→  }
    87→
    88→  // 8) [REJECT] The sidecar is from a higher slot than the sidecar's block's parent
    89→  if (parentBlock.slot >= blockHeader.slot) {
    90→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
    91→      code: DataColumnSidecarErrorCode.NOT_LATER_THAN_PARENT,
    92→      parentSlot: parentBlock.slot,
    93→      slot: blockHeader.slot,
    94→    });
    95→  }
    96→
    97→  // getBlockSlotState also checks for whether the current finalized checkpoint is an ancestor of the block.
    98→  // As a result, we throw an IGNORE (whereas the spec says we should REJECT for this scenario).
    99→  // this is something we should change this in the future to make the code airtight to the spec.
   100→  // 7) [REJECT] The sidecar's block's parent passes validation.
   101→  const blockState = await chain.regen
   102→    .getBlockSlotState(parentRoot, blockHeader.slot, {dontTransferCache: true}, RegenCaller.validateGossipDataColumn)
   103→    .catch(() => {
   104→      throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
   105→        code: DataColumnSidecarErrorCode.PARENT_UNKNOWN,
   106→        parentRoot,
   107→      });
   108→    });
   109→
   110→  // 13) [REJECT] The sidecar is proposed by the expected proposer_index for the block's slot in the context of the current
   111→  //              shuffling (defined by block_header.parent_root/block_header.slot). If the proposer_index cannot
   112→  //              immediately be verified against the expected shuffling, the sidecar MAY be queued for later processing
   113→  //              while proposers for the block's branch are calculated -- in such a case do not REJECT, instead IGNORE
   114→  //              this message.
   115→  const proposerIndex = blockHeader.proposerIndex;
   116→  const expectedProposerIndex = blockState.epochCtx.getBeaconProposer(blockHeader.slot);
   117→
   118→  if (proposerIndex !== expectedProposerIndex) {
   119→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   120→      code: DataColumnSidecarErrorCode.INCORRECT_PROPOSER,
   121→      actualProposerIndex: proposerIndex,
   122→      expectedProposerIndex,
   123→    });
   124→  }
   125→
   126→  // 5) [REJECT] The proposer signature of sidecar.signed_block_header, is valid with respect to the block_header.proposer_index pubkey.
   127→  const signatureSet = getBlockHeaderProposerSignatureSet(blockState, dataColumnSidecar.signedBlockHeader);
   128→  // Don't batch so verification is not delayed
   129→  if (
   130→    !(await chain.bls.verifySignatureSets([signatureSet], {
   131→      verifyOnMainThread: blockHeader.slot > chain.forkChoice.getHead().slot,
   132→    }))
   133→  ) {
   134→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   135→      code: DataColumnSidecarErrorCode.PROPOSAL_SIGNATURE_INVALID,
   136→    });
   137→  }
   138→
   139→  // 9) [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's block
   140→  //             -- i.e. get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch)
   141→  //                     == store.finalized_checkpoint.root
   142→  // Handled by 7)
   143→
   144→  // 10) [REJECT] The sidecar's kzg_commitments field inclusion proof is valid as verified by
   145→  //              verify_data_column_sidecar_inclusion_proof
   146→  //              TODO: Can cache result on (commitments, proof, header) in the future
   147→  const timer = metrics?.peerDas.dataColumnSidecarInclusionProofVerificationTime.startTimer();
   148→  const valid = verifyDataColumnSidecarInclusionProof(dataColumnSidecar);
   149→  timer?.();
   150→
   151→  if (!valid) {
   152→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   153→      code: DataColumnSidecarErrorCode.INCLUSION_PROOF_INVALID,
   154→      slot: dataColumnSidecar.signedBlockHeader.message.slot,
   155→      columnIdx: dataColumnSidecar.index,
   156→    });
   157→  }
   158→
   159→  const kzgProofTimer = metrics?.peerDas.dataColumnSidecarKzgProofsVerificationTime.startTimer();
   160→  // 11) [REJECT] The sidecar's column data is valid as verified by verify_data_column_sidecar_kzg_proofs
   161→  try {
   162→    await verifyDataColumnSidecarKzgProofs(
   163→      dataColumnSidecar.kzgCommitments,
   164→      Array.from({length: dataColumnSidecar.column.length}, () => dataColumnSidecar.index),
   165→      dataColumnSidecar.column,
   166→      dataColumnSidecar.kzgProofs
   167→    );
   168→  } catch {
   169→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   170→      code: DataColumnSidecarErrorCode.INVALID_KZG_PROOF,
   171→      slot: blockHeader.slot,
   172→      columnIdx: dataColumnSidecar.index,
   173→    });
   174→  } finally {
   175→    kzgProofTimer?.();
   176→  }
   177→
   178→  // 12) [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index,
   179→  //              sidecar.index) with valid header signature, sidecar inclusion proof, and kzg proof
   180→  //              -- Handled in seenGossipBlockInput
   181→}
   182→
   183→/**
   184→ * SPEC FUNCTION
   185→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar
   186→ */
   187→function verifyDataColumnSidecar(dataColumnSidecar: fulu.DataColumnSidecar): void {
   188→  if (dataColumnSidecar.index >= NUMBER_OF_COLUMNS) {
   189→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   190→      code: DataColumnSidecarErrorCode.INVALID_INDEX,
   191→      slot: dataColumnSidecar.signedBlockHeader.message.slot,
   192→      columnIdx: dataColumnSidecar.index,
   193→    });
   194→  }
   195→
   196→  if (dataColumnSidecar.kzgCommitments.length === 0) {
   197→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   198→      code: DataColumnSidecarErrorCode.NO_COMMITMENTS,
   199→      slot: dataColumnSidecar.signedBlockHeader.message.slot,
   200→      columnIdx: dataColumnSidecar.index,
   201→    });
   202→  }
   203→
   204→  if (
   205→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgCommitments.length ||
   206→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgProofs.length
   207→  ) {
   208→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   209→      code: DataColumnSidecarErrorCode.MISMATCHED_LENGTHS,
   210→      columnLength: dataColumnSidecar.column.length,
   211→      commitmentsLength: dataColumnSidecar.kzgCommitments.length,
   212→      proofsLength: dataColumnSidecar.kzgProofs.length,
   213→    });
   214→  }
   215→}
   216→
   217→/**
   218→ * SPEC FUNCTION
   219→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
   220→ */
   221→export async function verifyDataColumnSidecarKzgProofs(
   222→  commitments: Uint8Array[],
   223→  cellIndices: number[],
   224→  cells: Uint8Array[],
   225→  proofs: Uint8Array[]
   226→): Promise<void> {
   227→  let valid: boolean;
   228→  try {
   229→    valid = await kzg.asyncVerifyCellKzgProofBatch(commitments, cellIndices, cells, proofs);
   230→  } catch (e) {
   231→    (e as Error).message = `Error on asyncVerifyCellKzgProofBatch: ${(e as Error).message}`;
   232→    throw e;
   233→  }
   234→  if (!valid) {
   235→    throw Error("Invalid verifyCellKzgProofBatch");
   236→  }
   237→}
   238→
   239→/**
   240→ * SPEC FUNCTION
   241→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_inclusion_proof
   242→ */
   243→export function verifyDataColumnSidecarInclusionProof(dataColumnSidecar: fulu.DataColumnSidecar): boolean {
   244→  return verifyMerkleBranch(
   245→    ssz.deneb.BlobKzgCommitments.hashTreeRoot(dataColumnSidecar.kzgCommitments),
   246→    dataColumnSidecar.kzgCommitmentsInclusionProof,
   247→    KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH,
   248→    KZG_COMMITMENTS_SUBTREE_INDEX,
   249→    dataColumnSidecar.signedBlockHeader.message.bodyRoot
   250→  );
   251→}
   252→
   253→/**
   254→ * Validate a subset of data column sidecars in a block
   255→ *
   256→ * Requires the block to be known to the node
   257→ */
   258→export async function validateBlockDataColumnSidecars(
   259→  blockSlot: Slot,
   260→  blockRoot: Root,
   261→  blockBlobCount: number,
   262→  dataColumnSidecars: fulu.DataColumnSidecars
   263→): Promise<void> {
   264→  if (dataColumnSidecars.length === 0) {
   265→    return;
   266→  }
   267→
   268→  if (blockBlobCount === 0) {
   269→    throw new DataColumnSidecarValidationError(
   270→      {
   271→        code: DataColumnSidecarErrorCode.INCORRECT_SIDECAR_COUNT,
   272→        slot: blockSlot,
   273→        expected: 0,
   274→        actual: dataColumnSidecars.length,
   275→      },
   276→      "Block has no blob commitments but data column sidecars were provided"
   277→    );
   278→  }
   279→
   280→  // Hash the first sidecar block header and compare the rest via (cheaper) equality
   281→  const firstSidecarBlockHeader = dataColumnSidecars[0].signedBlockHeader.message;
   282→  const firstBlockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(firstSidecarBlockHeader);
   283→  if (Buffer.compare(blockRoot, firstBlockRoot) !== 0) {
   284→    throw new DataColumnSidecarValidationError(
   285→      {
   286→        code: DataColumnSidecarErrorCode.INCORRECT_BLOCK,
   287→        slot: blockSlot,
   288→        columnIdx: 0,
   289→        expected: toRootHex(blockRoot),
   290→        actual: toRootHex(firstBlockRoot),
   291→      },
   292→      "DataColumnSidecar doesn't match corresponding block"
   293→    );
   294→  }
   295→
   296→  const commitments: Uint8Array[] = [];
   297→  const cellIndices: number[] = [];
   298→  const cells: Uint8Array[] = [];
   299→  const proofs: Uint8Array[] = [];
   300→  for (let i = 0; i < dataColumnSidecars.length; i++) {
   301→    const columnSidecar = dataColumnSidecars[i];
   302→
   303→    if (columnSidecar.index >= NUMBER_OF_COLUMNS) {
   304→      throw new DataColumnSidecarValidationError(
   305→        {
   306→          code: DataColumnSidecarErrorCode.INVALID_INDEX,
   307→          slot: blockSlot,
   308→          columnIdx: columnSidecar.index,
   309→        },
   310→        "DataColumnSidecar has invalid index"
   311→      );
   312→    }
   313→
   314→    if (columnSidecar.kzgCommitments.length !== blockBlobCount) {
   315→      throw new DataColumnSidecarValidationError({
   316→        code: DataColumnSidecarErrorCode.INCORRECT_KZG_COMMITMENTS_COUNT,
   317→        slot: blockSlot,
   318→        columnIdx: columnSidecar.index,
   319→        expected: blockBlobCount,
   320→        actual: columnSidecar.kzgCommitments.length,
   321→      });
   322→    }
   323→
   324→    if (columnSidecar.kzgProofs.length !== columnSidecar.kzgCommitments.length) {
   325→      throw new DataColumnSidecarValidationError({
   326→        code: DataColumnSidecarErrorCode.INCORRECT_KZG_PROOF_COUNT,
   327→        slot: blockSlot,
   328→        columnIdx: columnSidecar.index,
   329→        expected: columnSidecar.kzgCommitments.length,
   330→        actual: columnSidecar.kzgProofs.length,
   331→      });
   332→    }
   333→
   334→    if (!verifyDataColumnSidecarInclusionProof(columnSidecar)) {
   335→      throw new DataColumnSidecarValidationError(
   336→        {
   337→          code: DataColumnSidecarErrorCode.INCLUSION_PROOF_INVALID,
   338→          slot: blockSlot,
   339→          columnIdx: columnSidecar.index,
   340→        },
   341→        "DataColumnSidecar has invalid inclusion proof"
   342→      );
   343→    }
   344→
   345→    commitments.push(...columnSidecar.kzgCommitments);
   346→    cellIndices.push(...Array.from({length: columnSidecar.column.length}, () => columnSidecar.index));
   347→    cells.push(...columnSidecar.column);
   348→    proofs.push(...columnSidecar.kzgProofs);
   349→  }
   350→
   351→  let reason: string | undefined;
   352→  try {
   353→    const valid = await kzg.asyncVerifyCellKzgProofBatch(commitments, cellIndices, cells, proofs);
   354→    if (!valid) {
   355→      reason = "Invalid KZG proof batch";
   356→    }
   357→  } catch (e) {
   358→    reason = (e as Error).message;
   359→  }
   360→  if (reason !== undefined) {
   361→    throw new DataColumnSidecarValidationError(
   362→      {
   363→        code: DataColumnSidecarErrorCode.INVALID_KZG_PROOF_BATCH,
   364→        slot: blockSlot,
   365→        reason,
   366→      },
   367→      "DataColumnSidecar has invalid KZG proof batch"
   368→    );
   369→  }
   370→}
   371→
   372→/**
   373→ * SPEC FUNCTION
   374→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#compute_subnet_for_data_column_sidecar
   375→ */
   376→export function computeSubnetForDataColumnSidecar(
   377→  config: ChainConfig,
   378→  columnSidecar: fulu.DataColumnSidecar
   379→): SubnetID {
